#!/bin/sh
# Clean all build artifacts (and their directories) from the Dobby repo.
#
# Removes everything that is generated by a build and NOT tracked by git:
#   - ./build                  (host CMake build)
#   - ./auto-build-output      (auto-build.sh stripped libs)
#   - ./auto-build-workspace   (auto-build.sh per-ABI build dirs)
#   - ./prefab                 (prefab copy of .a files)
#   - ./build-workspace/prefab (prefab copy produced by auto-build.sh)
#   - ./build-workspace/auto-build-workspace (stale build dir)
#   - ./tests/build            (smoke-test build output)
#
# The source tree (source/, include/, builtin-plugin/, external/, cmake/,
# docs/, example/, build-workspace/auto-build.sh) is left untouched.

set -e

DRY_RUN=0
if [ "$1" = "--dry-run" ] || [ "$1" = "-n" ]; then
  DRY_RUN=1
fi

# Script lives in build-workspace/, so the repo root is one level up.
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
REPO_ROOT=$(cd "$SCRIPT_DIR/.." && pwd)
cd "$REPO_ROOT"

# Directories that are purely build output and safe to delete wholesale.
CLEAN_DIRS="
  build
  auto-build-output
  auto-build-workspace
  prefab
  tests/build
"

# Inside build-workspace, only generated .a files (and the stale build dir) are
# removed. The tracked prefab metadata (module.json, abi.json, AndroidManifest)
# is preserved.
WORKSPACE_CLEAN="
  build-workspace/prefab
  build-workspace/auto-build-workspace
"

# Remove only build-generated content inside a directory, preserving tracked
# metadata files. Used for build-workspace/prefab.
rm_generated_only() {
  local dir="$1"
  if [ ! -d "$dir" ]; then
    return 0
  fi
  find "$dir" -type f \( -name "*.a" -o -name "*.so" \) -print 2>/dev/null | while read -r f; do
    if [ $DRY_RUN -eq 1 ]; then
      echo "  would remove: $f"
    else
      echo "  removing: $f"
      rm -f "$f"
    fi
  done
  # prune empty directories left behind by the removals
  if [ $DRY_RUN -ne 1 ]; then
    find "$dir" -type d -empty -delete 2>/dev/null || true
  fi
}

rm_safe() {
  if [ ! -e "$1" ]; then
    return 0
  fi
  if [ $DRY_RUN -eq 1 ]; then
    echo "  would remove: $1"
  else
    echo "  removing: $1"
    rm -rf "$1"
  fi
}

echo "Cleaning build artifacts in $REPO_ROOT"

for d in $CLEAN_DIRS; do
  rm_safe "$d"
done

# build-workspace/auto-build-workspace is fully generated -> remove wholesale
if [ -e "build-workspace/auto-build-workspace" ]; then
  if [ $DRY_RUN -eq 1 ]; then
    echo "  would remove: build-workspace/auto-build-workspace"
  else
    echo "  removing: build-workspace/auto-build-workspace"
    rm -rf build-workspace/auto-build-workspace
  fi
fi

# build-workspace/prefab: remove only the generated library files, keep metadata
rm_generated_only "build-workspace/prefab"

echo "Done."
if [ $DRY_RUN -eq 1 ]; then
  echo "(dry run — nothing was removed)"
fi
